package pe.ganadoconecta.modulos.reproduccion.adaptadores.entrada.http;import java.time.Instant;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.ganadoconecta.modulos.identidad.adaptadores.entrada.http.IdentidadAutenticada;import pe.ganadoconecta.modulos.reproduccion.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
@RestController @Profile("postgres") @RequestMapping("/api/v1/ganaderias/{ganaderiaId}/animales/{animalId}/genealogia") public class GenealogiaControlador{private final ConsultarGenealogia consultar;private final CorregirParentesco corregir;public GenealogiaControlador(ConsultarGenealogia c,CorregirParentesco x){consultar=c;corregir=x;}@GetMapping ResponseEntity<GenealogiaAnimal> consultar(@PathVariable UUID ganaderiaId,@PathVariable UUID animalId,@AuthenticationPrincipal IdentidadAutenticada i){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(consultar.ejecutar(i.usuarioId(),ganaderiaId,animalId));}@PutMapping("/{tipo}") ResponseEntity<Resultado> corregir(@PathVariable UUID ganaderiaId,@PathVariable UUID animalId,@PathVariable String tipo,@RequestBody Solicitud b,@AuthenticationPrincipal IdentidadAutenticada i){TipoParentesco t;try{t=TipoParentesco.valueOf(tipo);}catch(Exception x){throw new DatoReproductivoInvalidoException("tipo");}var r=corregir.ejecutar(new SolicitudParentesco(ganaderiaId,animalId,t,b.progenitorAnimalId(),b.operationId(),b.schemaVersion()==null?0:b.schemaVersion()),i.usuarioId(),i.sesionId());return ResponseEntity.status("APLICADO".equals(r.resultado())?201:200).cacheControl(CacheControl.noStore()).body(new Resultado(r.operationId(),r.animalId(),r.resultado(),r.confirmadoEn()));}record Solicitud(UUID operationId,Integer schemaVersion,UUID progenitorAnimalId){}record Resultado(UUID operationId,UUID animalId,String resultado,Instant confirmadoEn){}
}
